mapper.select:
select fll.template_id as alarm_flow_id,flic.link_id from vm_flow_link_industry_config flic INNER JOIN vm_flow_template_link as fll on flic.link_id = fll.cur_link INNER JOIN vm_flow_template as ft on ft.template_id = fll.template_id and flic.app_ver_code = ft.app_ver_code and flic.industry_code = ft.industry_code where flic.delete_flag = 0 and flic.app_ver_code =#{param.appVerCode} and flic.industry_code =#{param.industryCode}
and
FIND_IN_SET(#{item},flic.role_id)
GROUP BY fll.template_id,flic.link_id UNION all select fll.template_id as alarm_flow_id,flic.link_id from vm_flow_link_industry_config flic INNER JOIN vm_flow_template_link as fll on flic.link_id = fll.cur_link INNER JOIN vm_flow_template as ft on ft.template_id = fll.template_id and ft.app_ver_code is null and ft.industry_code is null where flic.delete_flag = 0 and flic.app_ver_code is null and flic.industry_code is null
and
FIND_IN_SET(#{item},flic.role_id)
GROUP BY fll.template_id,flic.link_id union all select attr.alarm_flow_id,r.link_id from vm_flow_link_role r LEFT JOIN vm_flow_link_attr attr on attr.id = r.attr_id where attr.tenant_id = #{param.tenantId} and attr.app_ver_code =#{param.appVerCode} and attr.industry_code =#{param.industryCode}
and r.role_id in
#{item}
GROUP BY attr.alarm_flow_id,r.link_id
